package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonLocation;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.core.base.ParserBase;
import com.fasterxml.jackson.core.io.CharTypes;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.core.sym.CharsToNameCanonicalizer;
import com.fasterxml.jackson.core.util.*;
import com.fasterxml.jackson.core.util.BufferRecycler;
import java.io.*;
import java.io.StringReader;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.mockito.Mockito.when;

/**
 * Unit tests for ReaderBasedJsonParser#getTokenLocation.
 */
public class ReaderBasedJsonParser_getTokenLocation_TriageGen2Test {

    private IOContext ioContext;
    private final String jsonInput = "{\"key\": \"value\"}";
    private final Object sourceReference = new Object();

    @Before
    public void setUp() {
        ioContext = Mockito.mock(IOContext.class);
        when(ioContext.getSourceReference()).thenReturn(sourceReference);
    }

    @Test
    public void testGetTokenLocation_ReturnsCorrectLocationDetails() throws Exception {
        // We use a real StringReader to drive the parser state
        // We need to advance the parser to a specific token to ensure getTokenCharacterOffset, etc., return non-zero values
        ReaderBasedJsonParser parser = new ReaderBasedJsonParser(
                ioContext,
                0,
                new StringReader(jsonInput),
                null,
                null
        );

        // Move to the first token (START_OBJECT '{')
        JsonToken token = parser.nextToken();
        Assert.assertEquals(JsonToken.START_OBJECT, token);

        // Capture the location
        JsonLocation location = parser.getTokenLocation();

        // Verify the location properties
        Assert.assertNotNull(location);
        Assert.assertEquals(sourceReference, location.getSourceRef());
        // The offset for the first token in the string is 0
        Assert.assertEquals(0L, location.getByteOffset()); 
        // Note: getTokenCharacterOffset() in Jackson is often used for character-based tracking
        // getTokenLineNr() and getTokenColumnNr() should be at least 1 for the first token
        Assert.assertTrue(location.getLineNr() >= 1);
        Assert.assertTrue(location.getColumnNr() >= 1);
    }

    @Test
    public void testGetTokenLocation_AfterMovingToValue() throws Exception {
        ReaderBasedJsonParser parser = new ReaderBasedJsonParser(
                ioContext,
                0,
                new StringReader(jsonInput),
                null,
                null
        );

        // Move through: { -> "key" -> : -> "value"
        parser.nextToken(); // START_OBJECT
        parser.nextToken(); // FIELD_NAME "key"
        parser.nextToken(); // VALUE_STRING "value"

        JsonLocation location = parser.getTokenLocation();

        Assert.assertNotNull(location);
        Assert.assertEquals(sourceReference, location.getSourceRef());

        // Verify that the location has advanced from the start
        // At the value "value", the line/column should be greater than the start
        Assert.assertTrue(location.getLineNr() >= 1);
        Assert.assertTrue(location.getColumnNr() > 1);
    }

    @Test
    public void testGetTokenLocation_WithNullSourceReference() throws Exception {
        // Test edge case where source reference might be null
        when(ioContext.getSourceReference()).thenReturn(null);

        ReaderBasedJsonParser parser = new ReaderBasedJsonParser(
                ioContext,
                0,
                new StringReader(jsonInput),
                null,
                null
        );

        parser.nextToken();
        JsonLocation location = parser.getTokenLocation();

        Assert.assertNotNull(location);
        Assert.assertNull(location.getSourceRef());
    }
}
